import 'dart:convert';import 'dart:io';import 'package:cross_file/cross_file.dart';import 'package:file_picker/file_picker.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:path/path.dart' as p;import 'package:path_provider/path_provider.dart';import 'package:path_provider/path_provider.dart';import '../../../core/providers/app_providers.dart';import 'package:share_plus/share_plus.dart';
class BackupScreen extends ConsumerStatefulWidget{const BackupScreen({super.key});@override ConsumerState<BackupScreen> createState()=>_BackupScreenState();}
class _BackupScreenState extends ConsumerState<BackupScreen>{String? status;bool busy=false;Future<void> export()async{setState(()=>busy=true);try{final data=await ref.read(appControllerProvider).exportData();final directory=await getTemporaryDirectory();final file=File(p.join(directory.path,'pawpal-backup-${DateTime.now().millisecondsSinceEpoch}.json'));await file.writeAsString(data,flush:true);await SharePlus.instance.share(ShareParams(files:[XFile(file.path)],subject:'PawPal local JSON backup'));}finally{if(mounted)setState(()=>busy=false);}}
Future<void> import()async{final picked=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(picked==null)return;final bytes=picked.files.single.bytes;if(bytes==null){setState(()=>status='The selected file could not be read.');return;}try{final source=utf8.decode(bytes);final c=ref.read(appControllerProvider);final validated=await c.validateBackup(source);final counts=validated.map((k,v)=>MapEntry(k,v.length));if(!mounted)return;final mode=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Review backup contents'),content:Text('Pets: ${counts['pets']}\nReminders: ${counts['reminders']}\nCare logs: ${counts['care_logs']}\nRecords: ${counts['pet_records']}\nFeeding entries: ${counts['feeding_entries']}\nActivity entries: ${counts['activity_entries']}\n\nChoose Replace to replace local records, or Merge to keep existing records when IDs conflict.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,null),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Merge')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Replace'))]));if(mode==null)return;final docs=await getApplicationDocumentsDirectory();final backup=File(p.join(docs.path,'pawpal-pre-restore-${DateTime.now().millisecondsSinceEpoch}.json'));await backup.writeAsString(await c.exportData(),flush:true);await c.restoreBackup(validated,replaceExisting:mode);if(mounted)setState(()=>status='Restore complete. A pre-restore backup was saved locally.');}catch(e){if(mounted)setState(()=>status='Import stopped safely: $e');}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Backup and restore')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Your backup stays under your control. PawPal does not upload it to a server.'),const SizedBox(height:14),FilledButton.icon(onPressed:busy?null:export,icon:const Icon(Icons.ios_share),label:const Text('Export JSON backup')),const SizedBox(height:10),OutlinedButton.icon(onPressed:busy?null:import,icon:const Icon(Icons.file_open),label:const Text('Import JSON backup')),if(status!=null)...[const SizedBox(height:14),SelectableText(status!)],const SizedBox(height:18),const Text('Import validates the schema, duplicate IDs and pet references before writing. A local pre-restore backup is created before the transaction. Attachments are not included in this JSON export; they remain in app-private storage on this device.') ]));}
